class SmallestInfiniteSet {
    int next = 1;
    set<int> returned;
public:
    SmallestInfiniteSet() {}
    int popSmallest() {
        if (!returned.empty()) { int x=*returned.begin(); returned.erase(returned.begin()); return x; }
        return next++;
    }
    void addBack(int num) { if (num < next) returned.insert(num); }
};
